scan_table_check.script:
(function (engine) {

    Log(x_snc_devtools.GetRecord('sys_user',current));

	var strUserName = x_snc_devtools.GetStringValue(current.user_name);

	if (strUserName == 'playbook.automation_runner')
	{
		return;
	}

	var strIdentityType = x_snc_devtools.GetStringValue(current.identity_type);
	if (strIdentityType == 'human')
	{
		return;
	}
	if (strIdentityType == 'ai_agent')
	{
		return;
	}
	if (strIdentityType == 'machine')
	{
		return;
	}

	engine.finding.increment();

})(engine);
